text(await tools.exec_command({cmd:"command -v entire","max_output_tokens":1000}));
text(await tools.exec_command({cmd:"pwd; rg --files -g AGENTS.md -g '*entire*' -g '!node_modules' -g '!vendor'","max_output_tokens":2000}));
text(await tools.web__run({search_query:[{q:"entire.io CLI install entire enable"}],response_length:"short"}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"git status --short --branch","max_output_tokens":2000}),
  tools.exec_command({cmd:"git branch --show-current","max_output_tokens":1000}),
  tools.exec_command({cmd:"entire status","max_output_tokens":2000}),
  tools.exec_command({cmd:"git log -1 --oneline","max_output_tokens":1000}),
  tools.exec_command({cmd:"git remote -v","max_output_tokens":1000})
]);
for (const x of r) text(x.status === "fulfilled" ? x.value.output : String(x.reason));

const r=await Promise.allSettled([
tools.exec_command({cmd:"rg --files --hidden .codex .entire","max_output_tokens":2000}),
tools.exec_command({cmd:"git check-ignore -v .codex .entire .codex/hooks.json .entire/settings.json","max_output_tokens":2000}),
tools.exec_command({cmd:"git status --porcelain=v2 --branch","max_output_tokens":2000}),
tools.exec_command({cmd:"git ls-files .codex .entire","max_output_tokens":1000})
]);
for (const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

const r=await Promise.allSettled([
tools.exec_command({cmd:"cat .entire/settings.json","max_output_tokens":2000}),
tools.exec_command({cmd:"cat .entire/.gitignore","max_output_tokens":1000}),
tools.exec_command({cmd:"cat .codex/hooks.json","max_output_tokens":3000}),
tools.exec_command({cmd:"git diff --stat; git status --short","max_output_tokens":1000})
]);
for (const x of r) text(x.status==="fulfilled"?x.value.output:String(x.reason));

